  panel.className = 'v13-panel';
  panel.style.cssText = 'display:block!important;visibility:visible!important;margin:18px 0 24px';
  panel.innerHTML = `<h2>Bluetooth Xbox Controller</h2>
    <div class="v13-stats">
      <div class="v13-stat"><small>Bluetooth</small><strong id="xblu-ready">Checking</strong></div>
      <div class="v13-stat"><small>Connection</small><strong id="xblu-connected">Checking</strong></div>
      <div class="v13-stat"><small>Controller</small><strong id="xblu-peer">—</strong></div>
      <div class="v13-stat"><small>Xbox 360 forwarding</small><strong id="xblu-forward">Checking</strong></div>
    </div>
    <div class="v13-tools"><button id="xblu-scan">Scan for controllers</button><button id="xblu-stop">Stop scan</button><button id="xblu-enable">Enable forwarding</button><button id="xblu-disable">Disable forwarding</button></div>
    <div id="xblu-devices" class="v13-info">Press Scan for controllers.</div>
    <h2 style="margin-top:18px">Live Bluetooth Input</h2>
    <div id="xblu-buttons" class="xblu-key-grid"></div>
    <div class="xblu-stick-row">
      <div class="xblu-stick" id="xblu-left"><strong>Left Stick · L3</strong><svg viewBox="0 0 120 120"><circle cx="60" cy="60" r="48" fill="#191426" stroke="#584573" stroke-width="3"/><path d="M60 13V107 M13 60H107" stroke="#49395d" stroke-width="1"/><circle class="xblu-dot" cx="60" cy="60" r="17" fill="#9a63e7" stroke="#dfb8ff" stroke-width="3"/></svg><small class="xblu-coords">0.00, 0.00</small></div>
      <div class="xblu-stick" id="xblu-right"><strong>Right Stick · R3</strong><svg viewBox="0 0 120 120"><circle cx="60" cy="60" r="48" fill="#191426" stroke="#584573" stroke-width="3"/><path d="M60 13V107 M13 60H107" stroke="#49395d" stroke-width="1"/><circle class="xblu-dot" cx="60" cy="60" r="17" fill="#9a63e7" stroke="#dfb8ff" stroke-width="3"/></svg><small class="xblu-coords">0.00, 0.00</small></div>
    </div>
    <div id="xblu-axes" class="v13-info" style="margin-top:12px">Waiting for input</div>
    <div id="xblu-message" class="v13-info" style="margin-top:12px">Initializing</div>`;
  page.prepend(panel);
  const get = id => panel.querySelector('#xblu-' + id);
  const labels = ['Up','Down','Left','Right','Start','Back','L3','R3','LB','RB','Guide','A','B','X','Y'];
  get('buttons').innerHTML = labels.map((name,i) => `<div class="xblu-key" data-native-bit="${i}">${name}</div>`).join('');
  let alive = true, busy = false, connecting = false, scanning = false, current = null, lastStatus = null, devices = [];
  let scanTimer = null, scanGeneration = 0;
  const cancelScanTimer = () => { clearTimeout(scanTimer); scanTimer = null; };
  const sleep = ms => new Promise(resolve => setTimeout(resolve,ms));
  const message = s => { if (alive) get('message').textContent = s; };
  const api = async (url, options = {}) => {
    const response = await fetch(url, {cache:'no-store', ...options});
    if (!response.ok) throw Error(`${url}: HTTP ${response.status}`);
    return response.json();
  };
  const post = (url, args={}) => api(url, {method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(args)});
  function renderDevices() {
    get('devices').replaceChildren();
    if (!devices.length) {get('devices').textContent='No devices found yet. Start scanning and wait a few seconds.';return;}
    devices.forEach((device,i) => {
      const line=document.createElement('div');line.className='xblu-device';
      const name=document.createElement('span');name.textContent=`${device.name||'Unknown'} — ${device.address||'No address'}${device.rssi!=null?' ('+device.rssi+' dBm)':''}`;
      const button=document.createElement('button');button.textContent='Connect';
      button.disabled = connecting || device.connectable === false;
      button.onclick=async()=>{
        if(connecting)return;
        connecting=true;
        try{
          cancelScanTimer();scanGeneration++;
          await post('/api/bluetooth/stop');
          scanning=false;
          await new Promise(resolve=>setTimeout(resolve,300));
          await loadDevices();
          if(!devices[i] || devices[i].address !== device.address)throw Error('Device list changed. Scan again.');
          message('Connecting to '+(device.name||device.address)+'...');
          await post('/api/bluetooth/connect',{index:String(i)});
          for(let attempt=0;attempt<20&&alive;attempt++){
            await new Promise(resolve=>setTimeout(resolve,750));
            const status=await api('/api/bluetooth/status');
            lastStatus=status;
            if(status.connected){message('Controller connected successfully.');return;}
            if(!status.connectPending && /failed|rejected|error|disconnect/i.test(status.event||''))throw Error(status.event);
          }
          message('Connection not confirmed: '+(lastStatus?.event||'Check controller pairing mode.'));
        }catch(e){message('Connection failed: '+e.message);}
        finally{connecting=false;renderDevices();}
      };
      line.append(name,button);get('devices').append(line);
    });
  }
  async function loadDevices() { try { const result=await api('/api/bluetooth/devices');devices=Array.isArray(result)?result:(result.devices||[]);renderDevices();}catch(e){message(e.message);} }
  get('scan').onclick=async()=>{
    if(connecting)return;
    cancelScanTimer();const generation=++scanGeneration;
    try{
      await post('/api/bluetooth/scan');
      if(!alive||generation!==scanGeneration)return;
      scanning=true;devices=[];renderDevices();
      message('Scanning for 2 seconds. Put the controller in pairing mode.');
      scanTimer=setTimeout(async()=>{
        if(!alive||generation!==scanGeneration||connecting)return;
        try{
          // Capture the discovered list before stopping; firmware retains its indices.
          await loadDevices();
          await post('/api/bluetooth/stop');
          scanning=false;
          await loadDevices();
          message(`2-second scan complete. ${devices.length} device(s) found. Select Connect.`);
        }catch(e){message('Scan stop error: '+e.message);}
      },2000);
    }catch(e){message('Scan failed: '+e.message);}
  };
  get('stop').onclick=async()=>{
    cancelScanTimer();scanGeneration++;
    try{await post('/api/bluetooth/stop');scanning=false;await loadDevices();message('Scan stopped');}
    catch(e){message(e.message);}
  };
  get('enable').onclick=async()=>{try{await post('/api/input/forward',{enabled:'true'});message('Forwarding enabled');}catch(e){message(e.message);}};
  get('disable').onclick=async()=>{try{await post('/api/input/forward',{enabled:'false'});message('Forwarding disabled');}catch(e){message(e.message);}};
  function renderState(s) {
    const mask=Number(s.mask)||0;
    get('buttons').querySelectorAll('[data-native-bit]').forEach((b,i)=>b.classList.toggle('down',!!(mask&(1<<i))));
    const v = name => Math.max(-1,Math.min(1,Number(s[name])||0));
    const lt=Math.max(0,v('lt')),rt=Math.max(0,v('rt'));
    get('axes').textContent=`LT ${Math.round(lt*100)}% · RT ${Math.round(rt*100)}% | LX ${v('lx').toFixed(2)} LY ${v('ly').toFixed(2)} | RX ${v('rx').toFixed(2)} RY ${v('ry').toFixed(2)} | Age ${s.ageMs??'?'}ms`;
    // Native BLE state reports screen-oriented Y on this firmware.
    // Add Y for the display; the USB output is not modified.
    const ids=['visD0','visD1','visD2','visD3','visStart','visBack','visLS','visRS','visLB','visRB','visGuide','visA','visB','visX','visY'];
    ids.forEach((id,i)=>document.getElementById(id)?.classList.toggle('lit',!!(mask&(1<<i))));
    const set=(id,attr,value)=>document.getElementById(id)?.setAttribute(attr,String(value));
    set('visLT','width',135*lt);set('visRT','width',135*rt);
    set('visLS','transform',`translate(${232+v('lx')*20} ${212+v('ly')*20})`);
    set('visRS','transform',`translate(${497+v('rx')*20} ${293+v('ry')*20})`);
    // Native L3/R3 flags: SVG stick groups aren't .vbtn elements, so
    // give them a dedicated pressed style and update our own stick views.
    for(const [id,bit,x,y] of [['left',6,v('lx'),v('ly')],['right',7,v('rx'),v('ry')]]){
      const holder=get(id),pressed=!!(mask&(1<<bit));
      holder.classList.toggle('pressed',pressed);
      holder.querySelector('.xblu-dot').setAttribute('cx',String(60+x*34));
      holder.querySelector('.xblu-dot').setAttribute('cy',String(60+y*34));
      holder.querySelector('.xblu-coords').textContent=`X ${x.toFixed(2)} · Y ${y.toFixed(2)}${pressed?' · CLICKED':''}`;
    }
    document.getElementById('visLS')?.classList.toggle('xblu-pressed',!!(mask&(1<<6)));
    document.getElementById('visRS')?.classList.toggle('xblu-pressed',!!(mask&(1<<7)));

    const label=document.getElementById('controllerName');
    if(label)label.textContent=lastStatus?.connected?(lastStatus.peer||'Bluetooth controller'):'Bluetooth: not connected';
    for(const [name,value] of [['lt',lt],['rt',rt]]){
      const bar=document.getElementById(name+'Bar'),txt=document.getElementById(name+'Text');
      if(bar)bar.style.width=(value*100)+'%';if(txt)txt.textContent=Math.round(value*100)+'%';
    }
    for(const [name,value] of [['LX',v('lx')],['LY',v('ly')],['RX',v('rx')],['RY',v('ry')]]){
      const bar=document.getElementById(name+'Bar'),txt=document.getElementById(name+'Text');
      if(bar)bar.style.width=((value+1)*50)+'%';if(txt)txt.textContent=value.toFixed(2);
    }
  }
  async function pollInput(){if(!alive||busy||document.hidden)return;busy=true;try{current=await api('/api/input/state');renderState(current);}catch(e){message('Input state error: '+e.message);}finally{busy=false;}}
  async function pollStatus(){if(!alive)return;try{const s=await api('/api/bluetooth/status');lastStatus=s;
    get('ready').textContent=s.ready?'Ready':'Not ready';
    get('connected').textContent=s.connected?'Connected':s.scanning?'Scanning':s.connectPending?'Connecting':'Disconnected';
    get('peer').textContent=typeof s.peer==='string'?(s.peer||'—'):'—';
    get('forward').textContent=s.xboxForwarding?'Enabled':'Disabled';
    if(s.event && !connecting)message(s.event);
    if(s.scanning && !connecting)await loadDevices();
  }catch(e){message('Bluetooth status error: '+e.message);}}
  const inputTimer=setInterval(pollInput,80);
  const statusTimer=setInterval(pollStatus,1200);
  // The original firmware renders at up to 60fps. Repaint AFTER its frame,
  // without modifying the USB or Bluetooth input path.
  let raf=0;
  function paint(){if(!alive)return;if(current&&!document.hidden&&page.hidden===false)renderState(current);raf=requestAnimationFrame(paint);}
  raf=requestAnimationFrame(paint);
  pollInput();pollStatus();
  window.XLinkProBluetoothUIStop=()=>{alive=false;scanGeneration++;cancelScanTimer();clearInterval(inputTimer);clearInterval(statusTimer);cancelAnimationFrame(raf);panel.remove();style.remove();document.getElementById('visLS')?.classList.remove('xblu-pressed');document.getElementById('visRS')?.classList.remove('xblu-pressed');delete window.XLinkProBluetoothUIStop;};
  document.querySelector('.nav[data-page="controller"]')?.click();
  panel.scrollIntoView({behavior:'smooth',block:'start'});
  message('Bluetooth panel installed. Scan or connect above.');
  return window.XLinkProBluetoothUIStop;
})()
